// Generated by ng-openapi-mock. Changes here are lost on the next run;
// put custom responses into overrides/ instead.
//
// Start:  node mock-server/server.mjs [--port 3000] [--delay 0]
import { existsSync, readFileSync } from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';

const here = path.dirname(fileURLToPath(import.meta.url));
const { values: args } = parseArgs({
  options: { port: { type: 'string' }, delay: { type: 'string' } },
  strict: false,
});
const port = Number(args.port ?? process.env.PORT ?? __DEFAULT_PORT__);
const delay = Number(args.delay ?? process.env.MOCK_DELAY ?? __DEFAULT_DELAY__);

const routes = JSON.parse(readFileSync(path.join(here, 'routes.json'), 'utf8')).map((route) => ({
  ...route,
  regex: new RegExp(route.pattern),
}));

function readBody(route) {
  const override = path.join(here, 'overrides', route.service, `${route.operation}.json`);
  const file = existsSync(override) ? override : route.file && path.join(here, route.file);
  if (!file || !existsSync(file)) return { body: null, overridden: false };
  return { body: JSON.parse(readFileSync(file, 'utf8')), overridden: file === override };
}

function corsHeaders(req) {
  return {
    'Access-Control-Allow-Origin': req.headers.origin ?? '*',
    'Access-Control-Allow-Credentials': 'true',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS',
    'Access-Control-Allow-Headers': req.headers['access-control-request-headers'] ?? '*',
    'Access-Control-Expose-Headers': '*',
  };
}

function send(req, res, status, headers, payload) {
  const finish = () => {
    res.writeHead(status, { ...corsHeaders(req), ...headers });
    res.end(payload);
  };
  if (delay > 0) setTimeout(finish, delay);
  else finish();
}

const server = http.createServer((req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (req.method === 'OPTIONS') {
    res.writeHead(204, corsHeaders(req));
    res.end();
    return;
  }
  const route = routes.find((r) => r.method === req.method && r.regex.test(pathname));
  if (!route) {
    console.log(`${req.method} ${pathname} -> 404`);
    send(req, res, 404, { 'Content-Type': 'application/json' },
      JSON.stringify({ error: 'No mock for this route', method: req.method, path: pathname }));
    return;
  }

  let result;
  try {
    result = readBody(route);
  } catch (err) {
    console.error(`${req.method} ${pathname} -> 500 (${route.id}): ${err.message}`);
    send(req, res, 500, { 'Content-Type': 'application/json' }, JSON.stringify({ error: err.message }));
    return;
  }
  const { body, overridden } = result;
  console.log(`${req.method} ${pathname} -> ${route.status} ${route.id}${overridden ? ' (override)' : ''}`);

  if (route.kind === 'none' && body == null) {
    send(req, res, route.status, {}, undefined);
  } else if (route.kind === 'blob') {
    send(req, res, route.status, { 'Content-Type': 'application/octet-stream' }, Buffer.alloc(0));
  } else if (route.kind === 'text' && typeof body === 'string') {
    send(req, res, route.status, { 'Content-Type': 'text/plain; charset=utf-8' }, body);
  } else {
    send(req, res, route.status === 204 ? 200 : route.status, { 'Content-Type': 'application/json' }, JSON.stringify(body));
  }
});

server.listen(port, () => {
  console.log(`Mock server with ${routes.length} routes running at http://localhost:${server.address().port}`);
});
